/* PlatformGPU>>fenceElapsed: */
int64_t pf_gpu_fence_elapsed(int fence)
{
    int64_t r;
    fence_watch *w;
    if (gpu_get(fence, K_FENCE, "fence") == NULL) {
        return -2;
    }
    r = -1;
    pthread_mutex_lock(watch_lock);
    if (fence < nwatches) {
        w = watches + fence;
        if ((w->f != NULL) && (w->done_us >= 0)) {
            r = w->done_us - w->submit_us;
        }
    }
    pthread_mutex_unlock(watch_lock);
    return r;
}

/* PlatformGPU>>fenceWatcher: */
static void *fence_watcher(void *unused)
{
    struct timespec local;
    struct timespec *nap;
    int32_t i;
    fence_watch *w;
    memset(&local, 0, sizeof local);
    nap = &local;
    pthread_mutex_lock(watch_lock);
    for (;;) {
        while (npending == 0) {
            pthread_cond_wait(watch_cond, watch_lock);
        }
        for (i = 0; i <= nwatches - 1; i++) {
            w = watches + i;
            if (w->active && SDL_QueryGPUFence(w->d, w->f)) {
                w->done_us = mono_us();
                w->active = false;
                npending = npending - 1;
            }
        }
        pthread_mutex_unlock(watch_lock);
        nap->tv_sec = 0;
        nap->tv_nsec = 200000;
        nanosleep(nap, (struct timespec *)NULL);
        pthread_mutex_lock(watch_lock);
    }
    __builtin_unreachable();
}

