/* PlatformGPU>>monoUs */
static int64_t mono_us(void)
{
    struct timespec local;
    struct timespec *ts;
    memset(&local, 0, sizeof local);
    ts = &local;
    clock_gettime(CLOCK_MONOTONIC, ts);
    return ts->tv_sec * 1000000 + ts->tv_nsec / 1000;
}

